CREATE OR REPLACE FUNCTION private.create_household(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare hid uuid; uid uuid := auth.uid();
begin
  if uid is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_name is null or length(btrim(p_name)) not between 1 and 100 then raise exception 'Invalid household name'; end if;
  insert into public.profiles(id) values(uid) on conflict(id) do nothing;
  insert into public.households(name,created_by) values(btrim(p_name),uid) returning id into hid;
  insert into public.household_members(household_id,user_id,role) values(hid,uid,'owner');
  return hid;
end $function$

CREATE OR REPLACE FUNCTION private.protect_person_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  -- A deliberate household deletion may cascade all of its people and items.
  if exists(select 1 from public.households where id=old.household_id)
    and exists(select 1 from public.calendar_items where household_id=old.household_id and person_ids @> array[old.id]) then
    raise exception 'Person is used by calendar items; deactivate instead' using errcode='23503';
  end if;
  return old;
end $function$

CREATE OR REPLACE FUNCTION private.revoke_household_invitation(p_invitation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare inv public.household_invitations;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 select * into inv from public.household_invitations where id=p_invitation_id for update;
 if not found or not private.is_household_admin(inv.household_id) then raise exception 'Forbidden' using errcode='42501'; end if;
 if inv.accepted_at is not null then raise exception 'Invitation already accepted'; end if;
 update public.household_invitations set revoked_at=coalesce(revoked_at,now()) where id=inv.id;
end $function$

CREATE OR REPLACE FUNCTION private.invite_household_member(p_household_id uuid, p_email text, p_role text DEFAULT 'adult'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare token text := gen_random_uuid()::text || gen_random_uuid()::text;
begin
  if not private.is_household_admin(p_household_id) then raise exception 'Forbidden' using errcode='42501'; end if;
  if p_role not in ('admin','adult','child') or p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Invalid invitation'; end if;
  if p_role='admin' and not exists(select 1 from public.household_members where household_id=p_household_id and user_id=auth.uid() and role='owner') then raise exception 'Only owners may invite admins'; end if;
  insert into public.household_invitations(household_id,email,role,token_hash,invited_by)
    values(p_household_id,lower(btrim(p_email)),p_role,encode(sha256(convert_to(token,'UTF8')),'hex'),auth.uid());
  return token;
end $function$

CREATE OR REPLACE FUNCTION private.accept_household_invitation(p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare inv public.household_invitations; verified_email text;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
  select lower(email) into verified_email from auth.users where id=auth.uid() and email_confirmed_at is not null;
  select * into inv from public.household_invitations
    where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
  if inv.id is null or inv.accepted_at is not null or inv.revoked_at is not null or inv.expires_at<=now()
    or verified_email is null or verified_email<>inv.email then raise exception 'Invalid or expired invitation'; end if;
  insert into public.profiles(id) values(auth.uid()) on conflict do nothing;
  insert into public.household_members(household_id,user_id,role) values(inv.household_id,auth.uid(),inv.role) on conflict do nothing;
  update public.household_invitations set accepted_at=now() where id=inv.id;
  return inv.household_id;
end $function$

CREATE OR REPLACE FUNCTION private.can_access_avatar(object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if array_length(string_to_array(object_name,'/'),1)<>3 then return false; end if;
  perform split_part(object_name,'/',2)::uuid;
  return private.is_household_member(split_part(object_name,'/',1)::uuid);
exception when invalid_text_representation then return false;
end $function$

CREATE OR REPLACE FUNCTION private.keep_person_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if length(btrim(new.name)) not between 1 and 100 then raise exception 'Invalid person name'; end if;
  if tg_op='UPDATE' and new.name is distinct from old.name then
    new.name_aliases=array(select distinct unnest(old.name_aliases || new.name_aliases || array[old.name]));
  end if;
  if new.avatar_path is not null and (
    split_part(new.avatar_path,'/',1)<>new.household_id::text or
    split_part(new.avatar_path,'/',2)<>new.id::text or
    array_length(string_to_array(new.avatar_path,'/'),1)<>3
  ) then raise exception 'Avatar path belongs to another person'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.validate_item_people()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  -- Lock referenced people until commit, so a concurrent delete cannot orphan an ID.
  perform 1 from public.household_people p where p.household_id=new.household_id and p.id=any(new.person_ids) for key share;
  if exists(select 1 from unnest(new.person_ids) pid where not exists(
    select 1 from public.household_people p where p.id=pid and p.household_id=new.household_id
  )) then raise exception 'Person belongs to another household'; end if;
  -- JSON is a compatibility mirror. Explicit columns are authoritative.
  new.data=jsonb_set(new.data,'{personIds}',to_jsonb(new.person_ids),true);
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.validate_feed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.feed_url !~* '^(https|webcal)://[^/[:space:]@]+(/|$)' or length(new.feed_url)>4096 then raise exception 'Invalid feed URL'; end if;
  if tg_op='UPDATE' and (new.source,new.feed_url,new.assigned_person_id,new.assigned_person_name,new.is_active)
    is distinct from (old.source,old.feed_url,old.assigned_person_id,old.assigned_person_name,old.is_active) then
    new.import_token=null; new.import_started_at=null;
    new.last_sync_status='pending'; new.last_sync_message=null;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.sync_calendar_mutation(p_mutation_id uuid, p_household_id uuid, p_expected jsonb, p_upserts jsonb, p_delete_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); receipt public.calendar_mutation_receipts; original_done jsonb; before_counts jsonb:='[]';
 week_start date; local_today date:=(now() at time zone 'Europe/Copenhagen')::date;
 person record; prior record; after_count integer; boundary integer; celebration public.reward_celebrations;
 celebrations jsonb:='[]'; versions jsonb; new_completion boolean; task_list jsonb; mutation_key text;
begin
 if uid is null or not private.is_household_member(p_household_id) then raise exception 'Household access denied' using errcode='42501'; end if;
 if p_mutation_id is null then raise exception 'Mutation ID required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_household_id::text,0));
 select * into receipt from public.calendar_mutation_receipts where id=p_mutation_id;
 if found then
   if receipt.household_id<>p_household_id or receipt.user_id<>uid then raise exception 'Mutation access denied' using errcode='42501'; end if;
   return jsonb_build_object('already_applied',true,'row_versions',receipt.row_versions,'celebrations','[]'::jsonb);
 end if;
 -- Compute before/after only for weeks with possible new completions. No load-time claims.
 for week_start in select distinct date_trunc('week',(e->>'date')::date)::date
   from jsonb_array_elements(p_upserts) e
   where e->>'type'='Opgave' and e->>'done'='true' and (e->>'date')::date<=local_today
 loop
   select coalesce(jsonb_agg(to_jsonb(t)),'[]') into original_done from private.completed_task_rows(p_household_id,week_start,least(week_start+6,local_today)) t;
   new_completion=false;
   for person in select e from jsonb_array_elements(p_upserts) e
     where e->>'type'='Opgave' and e->>'done'='true' and (e->>'date')::date between week_start and least(week_start+6,local_today)
   loop
     mutation_key=coalesce(nullif(person.e->'data'->>'overrideBaseId',''),nullif(person.e->'data'->>'overrideOf',''),person.e->>'id')||'|'||
       coalesce(nullif(person.e->'data'->>'originalDate',''),person.e->>'date');
     if not exists(select 1 from jsonb_array_elements(original_done) x where x->>'occurrence_key'=mutation_key)
       and not exists(select 1 from public.calendar_items old where old.id=(person.e->>'id')::uuid and old.household_id=p_household_id and old.type='Opgave' and old.done)
     then new_completion=true; end if;
   end loop;
   if not new_completion then continue; end if;
   for person in select * from public.household_people where household_id=p_household_id and reward_enabled loop
     select count(*) into after_count from private.completed_task_rows(p_household_id,week_start,least(week_start+6,local_today)) t
       where private.task_assigned_to(t.person_ids,t.people,person.id,person.name,person.name_aliases);
     before_counts=before_counts||jsonb_build_array(jsonb_build_object('person',person.id,'week',week_start,'count',after_count));
   end loop;
 end loop;
 -- Existing tenant and row validation is preserved. The definer entry point explicitly
 -- checks auth/membership above; mutate_calendar additionally validates every row tenant.
 perform public.mutate_calendar(p_household_id,p_expected,p_upserts,p_delete_ids);
 for prior in select * from jsonb_to_recordset(before_counts) as x(person uuid,week date,count integer) loop
   select * into person from public.household_people where id=prior.person and household_id=p_household_id and reward_enabled;
   if not found then continue; end if;
   select count(*) into after_count from private.completed_task_rows(p_household_id,prior.week,least(prior.week+6,local_today)) t
     where private.task_assigned_to(t.person_ids,t.people,person.id,person.name,person.name_aliases);
   select coalesce(jsonb_agg(x.title),'[]') into task_list from (
     select t.title from private.completed_task_rows(p_household_id,prior.week,least(prior.week+6,local_today)) t
     where private.task_assigned_to(t.person_ids,t.people,person.id,person.name,person.name_aliases) order by t.date desc,t.id limit 6
   ) x;
   foreach boundary in array array[7,9,12] loop
     if prior.count<boundary and after_count>=boundary then
       insert into public.reward_celebrations(household_id,person_id,iso_year,iso_week,threshold,completed_count,tasks)
       values(p_household_id,person.id,extract(isoyear from prior.week)::int,extract(week from prior.week)::int,boundary,after_count,task_list)
       on conflict(household_id,person_id,iso_year,iso_week,threshold) do nothing returning * into celebration;
       if found then celebrations=celebrations||jsonb_build_array(to_jsonb(celebration)); end if;
     end if;
   end loop;
 end loop;
 select coalesce(jsonb_object_agg(i.id,i.updated_at),'{}') into versions from public.calendar_items i
 where i.household_id=p_household_id and i.id in(select (e->>'id')::uuid from jsonb_array_elements(p_upserts) e);
 insert into public.calendar_mutation_receipts(id,household_id,user_id,row_versions) values(p_mutation_id,p_household_id,uid,versions);
 return jsonb_build_object('already_applied',false,'row_versions',versions,'celebrations',celebrations);
end $function$

CREATE OR REPLACE FUNCTION private.begin_account_deletion(p_user_id uuid, p_delete_households uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare required uuid[]; job public.account_deletion_jobs; uid_email text;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception 'Server only' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,5));
 perform 1 from auth.users where id=p_user_id for update;
 if not found then raise exception 'Account not found'; end if;
 select * into job from public.account_deletion_jobs where user_id=p_user_id;
 if found then return jsonb_build_object('household_ids',job.household_ids,'pending',true); end if;
 -- Lock the family parents before counting members; concurrent invitations/deletions serialize.
 perform 1 from public.households h where exists(select 1 from public.household_members m where m.household_id=h.id and m.user_id=p_user_id) order by h.id for update;
 select coalesce(array_agg(m.household_id order by m.household_id),'{}') into required
 from public.household_members m where m.user_id=p_user_id and m.role='owner'
 and not exists(select 1 from public.household_members n where n.household_id=m.household_id and n.role='owner' and n.user_id<>p_user_id);
 if required<>array(select distinct x from unnest(coalesce(p_delete_households,'{}')) x order by x) then
  raise exception 'Confirm each family where you are the only owner, or transfer ownership first' using errcode='23514';
 end if;
 if exists(select 1 from storage.objects where (owner_id=p_user_id::text or owner=p_user_id) and bucket_id<>'household-avatars') then
  raise exception 'Account owns unsupported storage objects' using errcode='23514';
 end if;
 insert into public.account_deletion_jobs(user_id,household_ids) values(p_user_id,required);
 -- Keep family-owned images for remaining members. Ownership metadata is not the access rule:
 -- the private bucket uses household membership. No files are deleted via SQL.
 update storage.objects set owner=null,owner_id=null where bucket_id='household-avatars' and (owner_id=p_user_id::text or owner=p_user_id);
 select lower(email) into uid_email from auth.users where id=p_user_id;
 delete from public.household_invitations where invited_by=p_user_id or lower(email)=uid_email;
 delete from public.calendar_feeds where household_id=any(required);
 delete from public.households where id=any(required);
 update public.households set created_by=null where created_by=p_user_id;
 update public.calendar_items set created_by=null where created_by=p_user_id;
 delete from public.native_devices where user_id=p_user_id;
 delete from public.calendar_mutation_receipts where user_id=p_user_id;
 delete from public.household_members where user_id=p_user_id;
 delete from public.profiles where id=p_user_id;
 return jsonb_build_object('household_ids',required,'pending',true);
end $function$

CREATE OR REPLACE FUNCTION private.block_deleting_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid;
begin
 if tg_table_name='households' then uid=new.created_by; elsif tg_table_name='household_members' then uid=new.user_id; else uid=new.id; end if;
 if uid is not null then
  perform 1 from auth.users where id=uid for update;
  if exists(select 1 from public.account_deletion_jobs where user_id=uid) then raise exception 'Account deletion in progress' using errcode='42501'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.guard_tenant_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.household_id is distinct from old.household_id then raise exception 'Household cannot be changed'; end if;
 if new.id is distinct from old.id then raise exception 'Row identity cannot be changed'; end if;
 if tg_table_name='calendar_items' then
 if new.created_by is distinct from old.created_by then
  if not (current_user in ('postgres','service_role') and new.created_by is null) then raise exception 'Creator cannot be changed'; end if;
 end if;
 end if;
 return new;
end $function$
